    """Sum all amicable numbers from 1 to n."""
    if n < 1:
        return 0

    # Create a list to store sum of proper divisors
    sum_of_divisors = [0] * (n + 1)

    # Initialize with 1 for all numbers >= 1
    for i in range(1, n + 1):
        sum_of_divisors[i] = 1

    # For each number, add its multiples
    for i in range(2, int(n ** 0.5) + 1):
