def answer(lower, upper):
    """
    Find two distinct numbers such that their LCM lies within [lower, upper].
    """
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    # Try pairs of distinct numbers
    # We want lcm(a, b) in [lower, upper]
    # Start with small numbers and check
    max_val = upper  # LCM can't exceed upper, so numbers likely <= upper
    for a in range(1, max_val + 1):
        for b in range(a + 1, max_val + 1):
            l = lcm(a, b)
            if l > upper:
                break
            if l >= lower:
                return (a, b)
    # If no pair found, return None (shouldn't happen for valid inputs)
    return None
