def newman_prime(n):
    """
    Find the nth Newman-Shanks-Williams prime number.
    NSW primes are primes of the form (NSW(n) + 1) / 2 where NSW(n) is the nth NSW number,
    or equivalently, they are primes p such that p divides NSW(k) for some k.

    The NSW numbers are defined by: NSW(1) = 1, NSW(2) = 3, and NSW(n) = 3*NSW(n-1) - NSW(n-2).
    A number p is a Newman-Shanks-Williams prime if p = (NSW(k) + 1) / 2 for some k.
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        if num == 3:
            return True
        if num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    a, b = 1, 3  # NSW(1), NSW(2)
    # Check NSW(1)
    val = (a + 1) // 2
    if is_prime(val):
        count += 1
        if count == n:
            return val
    # Check NSW(2)
    val = (b + 1) // 2
    if is_prime(val):
        count += 1
        if count == n:
            return val

    # Generate more NSW numbers
    for _ in range(3, 100000):
        a, b = b, 3 * b - a
        val = (b + 1) // 2
        if is_prime(val):
            count += 1
            if count == n:
                return val
    return None
