def is_subset_sum(arr, n, target_sum):
    # dp[i][s] is True if there is a subset of arr[0..i-1] with sum s
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # Base case: sum 0 is always possible with empty subset
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the table
    for i in range(1, n + 1):
        for s in range(1, target_sum + 1):
            # If arr[i-1] > s, it can't be included
            if arr[i - 1] > s:
                dp[i][s] = dp[i - 1][s]
            else:
                dp[i][s] = dp[i - 1][s] or dp[i - 1][s - arr[i - 1]]

    return dp[n][target_sum]
