            # Actually, the characters are 'o', 'x', and '.'. We can only change '.' to 'o'. 'o' stays 'o', 'x' stays 'x'.
            # So a window is valid only if it has no 'x'. The cost is the number of '.' in the window.

            # Use sliding window to count 'x' and '.'
            x_count = 0
