import sys
from functools import lru_cache

def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return

    # Parse the input - it's a list of integers
    nums = list(map(int, input_data.strip('[]').split(',')))

    n = len(nums)
    MOD = 10**9 + 7

    # Precompute which pairs are compatible
    # compatible[i][j] is True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                compatible[i][j] = True
            else:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    compatible[i][j] = True

    # DP: dp[mask][last] = number of ways to form a permutation using elements in mask, ending with element 'last'
    # mask is a bitmask of which elements have been used
    # last is the index of the last element in the permutation

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(mask, last):
        if mask == (1 << n) - 1:
            return 1

        count = 0
        for next_idx in range(n):
            if not (mask & (1 << next_idx)):  # next_idx not yet used
                if compatible[last][next_idx]:
                    count = (count + dp(mask | (1 << next_idx), next_idx)) % MOD
        return count % MOD

    total = 0
    for start in range(n):
        total = (total + dp(1 << start, start)) % MOD

    print(total % MOD)

solve()
